#include <iostream> using namespace std;
int inf=1000000008;
int minSteps(int m,int n) {
    if(n==m)return 0;
    if(m>n)return inf;
    int min_cost=inf;
    for(int i=2;i<m;i+=2) {
        if(m%i==0) {
            min_cost=min(min_cost,m/i+minSteps(m+i,n)) ;
        }
    }
    return min_cost;
}

