String countAndSay(int n) {
        if (n == 1) {
            return "1";
        }

        String say = countAndSay(n - 1);
        StringBuilder result = new StringBuilder();

        for (int i = 0; i < say.length(); i++) {
            int count = 1;
            char ch = say.charAt(i);

            while (i < say.length() - 1 && say.charAt(i) == say.charAt(i + 1)) {
                count++;
                i++;
            }

            result.append(count).append(ch);
        }

        return result.toString();
    }

TreeNode* bstFromPreorderHelper(const vector<int>& preorder,
                                    int left,
                                    int right,
                                    int *index) {

        if (*index == preorder.size() ||
            preorder[*index] < left ||
            preorder[*index] > right) {
            return nullptr;
        }

        auto root = new TreeNode(preorder[(*index)++]);
        root->left = bstFromPreorderHelper(preorder, left, root->val, index);
        root->right = bstFromPreorderHelper(preorder, root->val, right, index);
        return root;
    }

TreeNode* buildBT(vector<int>& inorder, vector<int>& postorder, int inStart, int inEnd, int postStart, int postEnd) {
        if(inStart > inEnd)
            return NULL;

        TreeNode* root = new TreeNode(postorder[postEnd]);
        int root_candidate = root->val;
        int i = inStart;

        //YOu can optimize this by storing index of inorder values in a map for direct access
        for(; i<=inEnd; i++) {
            if(inorder[i] == root_candidate) {
                break;
            }
        }
        int leftSize  = i-inStart;
        int rightSize = inEnd-i;

        root->left = buildBT(inorder, postorder, inStart, i-1, postStart, postStart+leftSize-1);
        root->right  = buildBT(inorder, postorder, i+1, inEnd, postEnd-rightSize, postEnd-1);

        return root;
    }

TreeNode* buildTree(vector<int>& A, int st, int en) {
      if(st > en) return NULL;
      int mid = (st + en) / 2;
      TreeNode* root = new TreeNode(A[mid]);
      root->left = buildTree(A, st, mid-1);
      root->right = buildTree(A, mid+1, en);
      return root;
    }

TreeNode* construct(const vector<int>& A, int l, int r){

        if(l > r) return NULL;

        int best_val = A[l], best_index = l;
        for(int i = l + 1; i <= r; i ++)
            if(A[i] > best_val)
                best_val = A[i], best_index = i;

        TreeNode* retNode = new TreeNode(A[best_index]);
        retNode->left = construct(A, l, best_index - 1);
        retNode->right = construct(A, best_index + 1, r);
        return retNode;
    }

TreeNode* construct(const vector<int>& nums, int l, int r){

        if(l > r) return nullptr;

        int max_index = max_element(nums.begin() + l, nums.begin() + (r + 1)) - nums.begin();
        TreeNode* ret = new TreeNode(nums[max_index]);
        ret->left = construct(nums, l, max_index - 1);
        ret->right = construct(nums, max_index + 1, r);
        return ret;
    }

TreeNode* construct(int l, int r, vector<int>& vec) {
        if(l > r)
            return NULL;

        int mid = l + (r-l)/2;
        TreeNode* root = new TreeNode(vec[mid]);

        root->left  = construct(l, mid-1, vec);
        root->right = construct(mid+1, r, vec);

        return root;
    }

TreeNode* dfs(const vector<string>& vec, int& index){

        if(index == vec.size() || vec[index] == "null")
            return NULL;

        TreeNode* node = new TreeNode(atoi(vec[index].c_str()));
        index ++;
        node->left = dfs(vec, index);

        index ++;
        node->right = dfs(vec, index);

        return node;
    }

TreeNode* solve(int prestart, int poststart, int preend, vector<int>& preorder, vector<int>& postorder) {
        if(prestart > preend) {
            return NULL;
        }

        TreeNode* root = new TreeNode(preorder[prestart]);
        if(prestart == preend) {
            return root;
        }
        int nextNode = preorder[prestart+1]; //root of left subtree

        int j = poststart;
        while(postorder[j] != nextNode) {
            j++;
        }

        int num = j - poststart + 1;

        root->left = solve(prestart+1, poststart, prestart+num, preorder, postorder);
        root->right = solve(prestart+num+1, j+1, preend, preorder, postorder);

        return root;
    }

TreeNode* solve(vector<int>& preorder, vector<int>& inorder, int start, int end, int& idx) {
        if(start > end)
            return NULL;

        int rootVal = preorder[idx];
        int i = start;

        for(; i <= end; i++) {
            if(inorder[i] == rootVal)
                break;
        }

        idx++;
        TreeNode* root = new TreeNode(rootVal);
        root->left  = solve(preorder, inorder, start, i-1, idx);
        root->right = solve(preorder, inorder, i+1, end, idx);

        return root;
    }

bool IsMatchHere(const string &regex, int regex_offset, const string &s,
                 int s_offset) {
  if (regex_offset == size(regex)) {
    // Case (1.): Empty regex matches all strings.
    return true;
  }

  if (regex_offset == size(regex) - 1 && regex[regex_offset] == '$') {
    // Case (2.): Reach the end of regex, and last char is '$'.
    return s_offset == size(s);
  }

  if (size(regex) - regex_offset >= 2 && regex[regex_offset + 1] == '*') {
    // Case (3.): A '*' match.
    // Iterate through s, checking '*' condition, if '*' condition holds,
    // performs the remaining checks.
    for (int i = s_offset + 1;
         i <= size(s) &&
         (regex[regex_offset] == '.' || regex[regex_offset] == s[i - 1]);
         ++i) {
      if (IsMatchHere(regex, regex_offset + 2, s, i)) {
        return true;
      }
    }
    // See '*' matches zero character in s[s_offset, size(s) - 1].
    return IsMatchHere(regex, regex_offset + 2, s, s_offset);
  }

  // Case (4.): regex begins with single character match.
  return s_offset < size(s) &&
         (regex[regex_offset] == '.' || regex[regex_offset] == s[s_offset]) &&
         IsMatchHere(regex, regex_offset + 1, s, s_offset + 1);
}

bool check(int num, int currnum, int target) {
        if(num == 0) {
            return currnum == target;
        }

        return check(num / 10, currnum + num % 10, target) ||
               check(num / 100, currnum + num % 100, target) ||
               check(num / 1000, currnum + num % 1000, target) ||
               check(num / 10000, currnum + num % 10000, target);
    }

bool check(string &s, int i, int j) {
        if(i >= j) {
            return true;
        }

        if(s[i] == s[j]) {
            return check(s, i+1, j-1);
        }

        return false;

    }

bool dfs(bool graph[101][101], int curr, int V, int m, vector<int> &colors)
{
  if (curr == V)
    return true;

  for (int c = 1; c <= m; ++c)
  {
    int flag = 0;
    colors[curr] = c;

    for (int i = 0; i < V; ++i)
    {
      if (graph[curr][i] && colors[i] == c)
      {
        flag = 1;
        break;
      }
    }

    if (!flag)
    {
      if (dfs(graph, curr + 1, V, m, colors))
        return true;
    }

    colors[curr] = 0;
  }

  return false;
}

bool dfs(const string& s, int index, const vector<string>& wordDict,
             vector<int>& dp){

        if(index == s.size()) return true;
        if(dp[index] != -1) return dp[index];

        int left = s.size() - index;
        for(const string& word: wordDict)
            if(left >= word.size() && s.substr(index, word.size()) == word &&
               dfs(s, index + word.size(), wordDict, dp)) return dp[index] = true;
        return dp[index] = false;
    }

bool dfs(int a[], int j, int k, int n, int vis[], int t, int c)
{
  if (c > t)
    return false;
  if (j == k)
    return true;
  if (c == t)
  {
    return dfs(a, j + 1, k, n, vis, t, 0);
  }

  for (int l = 0; l < n; ++l)
  {
    if (!vis[l])
    {
      vis[l] = 1;
      if (dfs(a, j, k, n, vis, t, c + a[l]))
        return true;
      vis[l] = 0;
    }
  }
  return false;
}

bool dfs(int curr, vector<int> adj[], vector<int> &rec, vector<int> &vis)
  {
    if (rec[curr])
      return true;

    rec[curr] = 1;

    for (auto &i : adj[curr])
    {
      if (!vis[i] && dfs(i, adj, rec, vis))
        return true;
    }

    vis[curr] = 1;
    rec[curr] = 0;
    return false;
  }

bool dfs(int curr, vector<int> adj[], vector<int> &vis, int par)
  {
    for (auto &i : adj[curr])
    {
      if (i != par)
      {
        if (vis[i])
          return true;
        vis[i] = 1;
        if (dfs(i, adj, vis, curr))
          return true;
      }
    }
    return false;
  }

