                if(dfs(s, index + 1, cnt, n, k)) return true;
            }
        return false;
    }

bool dfs(vector<int>& arr, int start, int& n) {
        if(start < 0 || start >= n || arr[start] < 0)
            return false;
        if(arr[start] == 0)
            return true;
        //I don't want to check start again in future
        //I could memoize it as well but making use of the fact
        //0 <= arr[i] < arr.length
        arr[start] = -arr[start];

        int left    = dfs(arr, start-arr[start], n);
        int right = dfs(arr, start+arr[start], n);

        return left||right;
    }

bool helper(int n, vector<int> &dp)
  {
    if (n == 0)
    {
      return false;
    }

    if (dp[n] != -1)
    {
      return dp[n];
    }

    for (int i = 1; i <= sqrt(n); i++)
    {
      bool x = helper(n - i * i, dp);
      if (!x)
      {
        dp[n] = 1;
        return true;
      }
    }

    dp[n] = 0;

    return false;
  }

bool isCycleDFS(vector<int> adj[], int u, vector<bool>& visited, vector<bool>& inRecursion) {
        visited[u] = true;
        inRecursion[u] = true;


        for(int &v : adj[u]) {
            //if not visited, then we check for cycle in DFS
            if(visited[v] == false && isCycleDFS(adj, v, visited, inRecursion))
                return true;
            else if(inRecursion[v] == true)
                return true;
        }

        inRecursion[u] = false;
        return false;

    }

bool isCycleUtil(vector<int> g[], int start, vector<bool>& visited, int parent) {
    visited[start] = true;

    vector<int>::iterator it;
    for(it = g[start].begin(); it != g[start].end(); it++) {
        if(*it == parent)
            continue;
        if(visited[*it] == true)
            return true;
        if(isCycleUtil(g, *it, visited, start))
            return true;

    }
    return false;
}

bool isMatch(string text, string pattern) {
        if (pattern.length() == 0) {
            return text.length() == 0;
        }

        bool first_char_matched = false;
        if(text.length() > 0 && (pattern[0] == text[0] || pattern[0] == '.')) {
            first_char_matched = true;
        }

        //Best example to understand : s = "aaab", p = "a*b"
        if (pattern.length() >= 2 && pattern[1] == '*') {
            return (isMatch(text, pattern.substr(2)) ||
                    (first_char_matched && isMatch(text.substr(1), pattern)));
        } else {
            return first_char_matched && isMatch(text.substr(1), pattern.substr(1));
        }
    }

