int atMostNGivenDigitSet(const string& dset, const string& snum){

        int dnum = snum.size();
        if(snum.size() == 0)
            return 1;

        int res = 0;
        for(int i = 0; i < dset.size(); i ++)
            if(dset[i] < snum[0])
                res += (int)pow(dset.size(), snum.size() - 1);
            else if(dset[i] == snum[0])
                res += atMostNGivenDigitSet(dset, snum.substr(1));
            else
                break;

        return res;
    }

int atMostNGivenDigitSet(const string& dset, const string& snum,
                             vector<int>& dp){

        if(snum.size() == 0)
            return 1;

        if(dp[snum.size()] != -1)
            return dp[snum.size()];

        int res = 0;
        for(int i = 0; i < dset.size(); i ++)
            if(dset[i] < snum[0])
                res += (int)pow(dset.size(), snum.size() - 1);
            else if(dset[i] == snum[0])
                res += atMostNGivenDigitSet(dset, snum.substr(1), dp);
            else
                break;

        return dp[snum.size()] = res;
    }

int atMostNGivenDigitSet(const string& dset, int N, int d){

        int dnum = to_string(N).size();
        if(dnum < d)
            return 0;
        if(dnum == 1){
            int res = 0;
            for(char c: dset)
                if(c - '0' <= N)
                    res ++;
            return res;
        }

        int res = 0;
        char leftmost = to_string(N)[0];
        for(int i = 0; i < dset.size(); i ++)
            if(dset[i] < leftmost)
                res += (int)pow(dset.size(), dnum - 1);
            else if(dset[i] == leftmost)
                res += atMostNGivenDigitSet(dset, N - (leftmost - '0') * pow(10, dnum - 1), dnum - 1);
            else
                break;

        return res;
    }

