int binarySearch(int arr[], int l, int r, int x)
{
    if (r >= l)
    {
        int mid = l + (r - l)/2;
        if (arr[mid] == x)
            return mid;
        if (arr[mid] > x)
            return binarySearch(arr, l, mid-1, x);

        return binarySearch(arr, mid+1, r, x);
    }
    return -1;
}

int binary_search(const vector<int>& nums, int l, int r){

        if(l == r) return l;

        int mid = (l + r) / 2;
        if(mid + 1 <= r && nums[mid] > nums[mid + 1])
            return binary_search(nums, l, mid);
        return binary_search(nums, mid + 1, r);
    }

int binary_search(int arr[],int start,int end,int y,int &count)
{
    if(start>=end)
        return start;
    int mid=(start+end)/2;
    count++;
    if(arr[mid]>y)
        end=mid;
    else
        start=mid+1;

    int pos=binary_search(arr,start,end,y,count);
        return pos;
}

