int countSubsets(int idx, int currOr, vector<int>& nums, int maxOr) {
        if(idx == nums.size()) {
            if(currOr == maxOr)
                return 1; //Found one subset
            return 0;
        }

        //Take nums[idx]
        int takeCount = countSubsets(idx+1, currOr | nums[idx], nums, maxOr);

        //Not taken nums[idx]
        int notTakeCount = countSubsets(idx+1, currOr, nums, maxOr);


        return takeCount + notTakeCount;

    }

int dfs(const string& s, int start, set<string>& bag){

        if(start == s.size())
            return bag.size();

        int res = 0;
        for(int end = start; end <= s.size(); end ++)
            if(!bag.count(s.substr(start, end - start + 1))){
                bag.insert(s.substr(start, end - start + 1));
                res = max(res, dfs(s, end + 1, bag));
                bag.erase(s.substr(start, end - start + 1));
            }
        return res;
    }

int dfs(const vector<int>& A, int start, int K, vector<int>& dp){

        if(start == A.size()) return 0;
        if(dp[start] != -1) return dp[start];

        int maxv = A[start];
        int res = 0;
        for(int end = start; end <= min(start + K - 1, (int)A.size() - 1); end ++){
            maxv = max(maxv, A[end]);
            res = max(res, maxv * (end - start + 1) + dfs(A, end + 1, K, dp));
        }
        return dp[start] = res;
    }

int dfs(const vector<int>& arr, int d, int pos, vector<int>& dp){

        if(dp[pos] != -1) return dp[pos];

        int res = 1;
        for(int i = pos - 1; i >= 0 && i >= pos - d; i --)
            if(arr[i] < arr[pos])
                res = max(res, 1 + dfs(arr, d, i, dp));
            else break;

        for(int i = pos + 1; i < arr.size() && i <= pos + d; i ++)
            if(arr[i] < arr[pos])
                res = max(res, 1 + dfs(arr, d, i, dp));
            else break;

        return dp[pos] = res;
    }

int dfs(const vector<int>& days, int index, int n, const vector<int>& costs, vector<int>& dp){

        if(index >= n) return 0;
        if(dp[index] != -1) return dp[index];

        int res = costs[0] + dfs(days, index + 1, n, costs, dp);

        int i1 = 0;
        for(; i1 < n; i1 ++)
            if(days[i1] >= days[index] + 7) break;
        res = min(res, costs[1] + dfs(days, i1, n, costs, dp));

        int i2 = 0;
        for(; i2 < n; i2 ++)
            if(days[i2] >= days[index] + 30) break;
        res = min(res, costs[2] + dfs(days, i2, n, costs, dp));

        return dp[index] = res;
    }

int dfs(const vector<int>& days, int index, int n, const vector<int>& costs, vector<int>& dp){

        if(index >= n) return 0;
        if(dp[index] != -1) return dp[index];

        int res = costs[0] + dfs(days, index + 1, n, costs, dp);

        int i1 = upper_bound(days.begin(), days.end(), days[index] + 6) - days.begin();
        res = min(res, costs[1] + dfs(days, i1, n, costs, dp));

        int i2 = upper_bound(days.begin(), days.end(), days[index] + 29) - days.begin();
        res = min(res, costs[2] + dfs(days, i2, n, costs, dp));

        return dp[index] = res;
    }

int dfs(const vector<int>& nums, int index, int res, int S){

        if(index == nums.size())
            return res == S;

        int ret = 0;
        ret += dfs(nums, index + 1, res - nums[index], S);
        ret += dfs(nums, index + 1, res + nums[index], S);
        return ret;
    }

int dfs(const vector<int>& v, int index, int k, int last, vector<int>& dp){

        if(index >= last) return 0;
        if(dp[index] != -1) return dp[index];

        int cur = v[index];
        int res = (cur - k) * (cur - k) + dfs(v, index + 1, k, last, dp);
        for(int i = index + 1; i < v.size(); i ++)
            if(cur + 1 + v[i] <= k){
                if(i + 1 == v.size()) return 0;
                cur += (1 + v[i]);
                res = min(res, (cur - k) * (cur - k) + dfs(v, i + 1, k, last, dp));
            }
            else break;
        return dp[index] = res;
    }

int dfs(int N, vector<int>& dp){

        if(N <= 1) return N;
        if(dp[N] >= 0) return dp[N];
        return dp[N] = dfs(N - 1, dp) + dfs(N - 2, dp);
    }

int dfs(int n, int cur, const vector<int>& cost, int& res){

        if(2 * cur + 1 >= n) return cost[cur];

        int l = dfs(n, 2 * cur + 1, cost, res);
        int r = dfs(n, 2 * cur + 2, cost, res);
        res += abs(l - r);
        return max(l, r) + cost[cur];
    }

int dfs(int n, int index, vector<bool>& used){

        if(index == n + 1) return 1;

        int res = 0;
        for(int num = 1; num <= n; num ++)
            if(!used[num] && (num % index == 0 || index % num == 0)){
                used[num] = true;
                res += dfs(n, index + 1, used);
                used[num] = false;
            }
        return res;
    }

int dfs(int n, int index, vector<int>& row,
            vector<bool>& col, vector<bool>& dia1, vector<bool>& dia2){

        if(index == n)
            return 1;

        int res = 0;
        for(int i = 0; i < n; i ++)
            if(!col[i] && !dia1[index + i] && !dia2[index - i + n - 1]){
                row.push_back(i);
                col[i] = true;
                dia1[index + i] = true;
                dia2[index - i + n - 1] = true;

                res += dfs(n, index + 1, row, col, dia1, dia2);

                col[i] = false;
                dia1[index + i] = false;
                dia2[index - i + n - 1] = false;
                row.pop_back();
            }
        return res;
    }

int dfs(string &s, int i, int prev, int memo[100001][2])
    {
        if (i == s.size())
            return 0;

        if (memo[i][prev] != -1)
            return memo[i][prev];

        int ans = INT_MAX;

        if (prev == 0)
        {
            ans = min(ans, (s[i] == '1' ? 1 : 0) + dfs(s, i + 1, 0, memo));
            ans = min(ans, (s[i] == '1' ? 0 : 1) + dfs(s, i + 1, 1, memo));
        }
        else
        {
            ans = min(ans, (s[i] == '1' ? 0 : 1) + dfs(s, i + 1, 1, memo));
        }

        return memo[i][prev] = ans;
    }

int dfs(string &s, int i, vector<int> &memo)
    {
        if (s.size() == i)
            return 1;

        if (s[i] == '0')
            return 0;

        if (memo[i] != -1)
            return memo[i];

        int ans = 0;
        ans += dfs(s, i + 1, memo);

        if (i + 1 < s.size())
        {
            if (s[i] == '1' || (s[i] == '2' && s[i + 1] <= '6'))
            {
                ans += dfs(s, i + 2, memo);
            }
        }

        return memo[i] = ans;
    }

int dfs(string& s, int l, int r){

        if(l >= r) return 0;
        if(s[l] == s[r]) return dfs(s, l + 1, r - 1);

        int front_pos, tail_pos, front_swaps = 0, tail_swaps = 0;
        for(front_pos = l; front_pos <= r && s[front_pos] != s[r]; front_pos ++, front_swaps ++);
        for(tail_pos = r; tail_pos >= l && s[tail_pos] != s[l]; tail_pos --, tail_swaps ++);


        if(front_swaps <= tail_swaps){
            for(int i = front_pos - 1; i >= l; i --) swap(s[i], s[i + 1]);
            return front_swaps + dfs(s, l + 1, r - 1);
        }

        for(int i = tail_pos + 1; i <= r; i ++) swap(s[i - 1], s[i]);
        return tail_swaps + dfs(s, l + 1, r - 1);
    }

int dfs(vector<int>& pos, int index, vector<int>& neg){

        if(index == pos.size()) return 0;

        int res = INT_MAX;
        for(int& e: neg){
            if(e){
                int t = min(pos[index], e);
                pos[index] -= t;
                e -= t;
                res = min(res, 1 + dfs(pos, index + (pos[index] == 0), neg));
                pos[index] += t;
                e += t;
            }
        }
        return res;
    }

int dfs(vector<string>& A, int i, vector<int>& masks, int mask) {
        if(i == A.size()) return 0;

        int ans = dfs(A, i+1, masks, mask);

        if((mask & masks[i]) == 0) {
            mask = mask | masks[i];
            ans = max(ans, (int)A[i].size() + dfs(A, i+1, masks, mask));
        }

        return ans;
    }

int divideConquer(vector<int>& nums, int l, int r) {
        if(l > r) {
            return INT_MIN;
        }

        int mid   = l + (r-l)/2;
        int Lsum  = divideConquer(nums, l, mid-1);
        int Rsum  = divideConquer(nums, mid+1, r);

        int leftSum  = 0;
        int rightSum = 0;
        int tempSum  =  0 ;
        for(int i = mid-1; i >= l; i--) {
            tempSum += nums[i];
            leftSum = max(leftSum, tempSum);
        }

        tempSum = 0;
        for(int i = mid+1; i <= r; i++) {
            tempSum += nums[i];
            rightSum = max(rightSum, tempSum);
        }

        return max({Lsum, Rsum, leftSum + rightSum + nums[mid]});
    }

