int findResult(const vector<int>& scores,
                   int index, int lastIndex, vector<int>& dp){

        if(index > lastIndex)
            return 0;

        if(dp[index] != -1)
            return dp[index];

        if(index == lastIndex)
            return dp[index] = scores[index];

        return dp[index] = max(findResult(scores, index + 1, lastIndex, dp),
                               scores[index] + findResult(scores, index + 2, lastIndex, dp));
    }

int findWinnerIdx(int n, int k) {
        if (n == 1) {
            return 0; // index
        }

        int idx = findWinnerIdx(n - 1, k);
        idx = (idx + k) % n; // to find the original index in the original array

        return idx;
    }

