int gcd(int num1, int num2) {
    if (num1 <= 0 | num2 <= 0) {
        throw std::domain_error("Euclidean algorithm domain is for ints > 0");
    }

    if (num1 == num2) {
        return num1;
    }

    // Everything divides 0
    if (num1 == 0)
        return num2;
    if (num2 == 0)
        return num1;

    // base case
    if (num1 == num2)
        return num1;

    // a is greater
    if (num1 > num2)
        return gcd(num1 - num2, num2);
    return gcd(num1, num2 - num1);
}

int gcd(int x, int y){

        if(x < y) swap(x, y);

        if(x % y == 0) return y;
        return gcd(y, x % y);
    }

int gcd(long long a, long long b){

        if(a > b) swap(a, b);

        if (a == 0) return b;
        return gcd(b % a, a);
    }

int gcd_impl(int a, int b) {
    if (b == 0) {
        return a;
    }
    if (b == 1) {
        return 1;
    }
    int remainder = a % b;

    if (remainder == 0) {
        return b;
    }
    return gcd_impl(a, remainder);
}

int gcd_two(int x, int y) {
  // base cases
  if (y == 0) {
    return x;
  }
  if (x == 0) {
    return y;
  }
  return gcd_two(y, x % y); // Euclidean method
}

