int kthGrammar(int N, int K) {
        if(N == 1 && K == 1)
            return 0;
        int mid = pow(2, N-1)/2;

        if(K <= mid)
            return kthGrammar(N-1, K);

        return !kthGrammar(N-1, K-mid);
    }

int lps(string s)
{
  int n = s.size(), len = 0;
  vector<int> lps(n, 0);
  lps[0] = 0;

  int i = 1;
  while (i < n)
  {
    if (s[i] == s[len])
    {
      len++;
      lps[i] = len;
      i++;
    }
    else
    {
      if (len != 0)
        len = lps[len - 1];
      else
      {
        lps[i] = 0;
        i++;
      }
    }
  }
  return lps[n - 1];
}

