int median_of_medians(const std::vector<int>& A,  const int& idx) {
    int pivot = 0;                    // initialized with zero
    std::vector<int> a(A.begin(), A.end());
    std::vector<int> m;
    int r = a.size();
    for(int i = 0; i < r; i += 5){
        std::sort(a.begin() + i, a.begin() + std::min(r, i + 5));
        int mid = (i + std::min(r, i + 5)) / 2;
        m.push_back(a[mid]);
    }
    int sz = int(m.size());
    if(sz <= 5){
        std::sort(m.begin(), m.end());
        pivot = m[(sz- 1) / 2];
    }
    else{
        pivot = median_of_medians(m, idx);
    }
    std::vector<int> low;
    std::vector<int> high;
    for(int i = 0; i < r; i++){
        if(a[i] < pivot){
            low.push_back(a[i]);
        }
        else if(a[i] > pivot){
            high.push_back(a[i]);
        }
    }
    int k = int(low.size());
    if(idx < k){
        return median_of_medians(low, idx);
    }
    else if(idx > k){
        return median_of_medians(high, idx-k-1);
    }
    else{
        return pivot;
    }
}

int nCr(int n, int r) {
    if (n < r)
        return 0;

    if (r == 0)
        return 1;

    return n * nCr(n - 1, r - 1) / r;
}

int numSquares(int n, vector<int>& mem){

        if(n == 0)
            return 0;

        if(mem[n] != -1)
            return mem[n];

        int res = INT_MAX;
        for(int i = 1; n - i * i >= 0; i ++ )
            res = min(res, 1 + numSquares(n - i * i, mem));
        return mem[n] = res;
    }

int numberOfSteps(int num)
  {
    if (num == 0)
      return 0;
    int ans = 0;
    if (num % 2 == 0)
      ans += numberOfSteps(num / 2);
    else
      ans += numberOfSteps(num - 1);
    return ans + 1;
  }

int packRecursive(int n, int W, int *w, int *v) {
    // 结束条件（初始条件），i或者j为0时最大总价值为0
    if (n == 0 || W == 0) {
        return 0;
    }
    // 第i个物品不能装下，则递归装i-1个
    if (w[n] > W) {
        return packRecursive(n - 1, W, w, v);
    }
    //第i个物品能装下，则比较包括第i个物品和不包括第i个物品，取其最大值
    else {
        return max(v[n] + packRecursive(n - 1, W - w[n], w, v), packRecursive(n - 1, W, w, v));
    }
}

