int power_rec(int base, int exp, int mod) {
    if (exp == 0) {
        return 1;
    }

    int p = power_rec((base * base) % mod, exp >> 1, mod);

    return (exp & 1) ? (p * base) % mod : p;
}

int querySegmentTree(int start, int end, int i, int l, int r, int segmentTree[]) {
    if (l > end || r < start) {
        return INT_MAX;
    }

    if (l >= start && r <= end) {
        return segmentTree[i];
    }

    int mid = l + (r - l) / 2;
    return min(querySegmentTree(start, end, 2 * i + 1, l, mid, segmentTree),
               querySegmentTree(start, end, 2 * i + 2, mid + 1, r, segmentTree));
}

int querySegmentTree(int start, int end, int i, int l, int r, int segmentTree[], vector<int>& heights) {
        if (l > end || r < start) {
            return -1; // Return -1 for out-of-bound queries
        }

        if (l >= start && r <= end) {
            return segmentTree[i]; // Return the index of the maximum element
        }

        int mid = l + (r - l) / 2;
        int leftIndex = querySegmentTree(start, end, 2 * i + 1, l, mid, segmentTree, heights);
        int rightIndex = querySegmentTree(start, end, 2 * i + 2, mid + 1, r, segmentTree, heights);

        // Handle cases where one side is out of bounds
        if (leftIndex == -1)
            return rightIndex;
        if (rightIndex == -1)
            return leftIndex;

        // Return the index of the maximum element
        return (heights[leftIndex] >= heights[rightIndex]) ? leftIndex : rightIndex;
    }

int querySegmentTree(int start, int end, int i, int l, int r, vector<int>& segmentTree) {
        if(l > end || r < start) {
            return 0;
        }

        if(l >= start && r <= end) {
            return segmentTree[i];
        }

        int mid = l + (r-l)/2;
        return querySegmentTree(start, end, 2*i+1, l,    mid, segmentTree) +
               querySegmentTree(start, end, 2*i+2, mid+1, r, segmentTree);
    }

int score(const string& s, int l, int r){

        int res = 0;

        int balance = 0;
        int start = l;
        for(int i = l ; i <= r ; i ++){
            if(s[i] == '(')
                balance ++;
            else{
                balance --;

                if(balance == 0){
                    if(l + 1 == i)
                        res += 1;
                    else
                        res += 2 * score(s, l + 1, i - 1);
                    l = i + 1;
                }
            }
        }
        return res;
    }

int select(const vector<int>& nums1, int l1, int r1,
               const vector<int>& nums2, int l2, int r2, int k){

        if(l1 > r1) return nums2[l2 + k];
        if(l2 > r2) return nums1[l1 + k];

        int len1 = r1 - l1 + 1, len2 = r2 - l2 + 1;
        int mid1 = len1 / 2, mid2 = len2 / 2;
        int e1 = nums1[l1 + mid1], e2 = nums2[l2 + mid2];
        if(mid1 + mid2 < k){
            if(e1 > e2)
                return select(nums1, l1, r1, nums2, l2 + mid2 + 1, r2, k - mid2 - 1);
            else
                return select(nums1, l1 + mid1 + 1, r1, nums2, l2, r2, k - mid1 - 1);
        }
        else{
            if(e1 > e2)
                return select(nums1, l1, l1 + mid1 - 1, nums2, l2, r2, k);
            else
                return select(nums1, l1, r1, nums2, l2, l2 + mid2 - 1, k);
        }
    }

int solve(int i, vector<int>& nums, int Xor) {
        if(i == nums.size()) {
            return Xor;
        }

        int include = solve(i+1, nums, nums[i] ^ Xor);
        int exclude = solve(i+1, nums, Xor);

        return include + exclude;
    }

int solve(int n, int p) {
        if(n == 0) {
            return true;
        }

        if(pow(3, p) > n) {
            return false;
        }

        bool p_ko_lelo = solve(n - pow(3, p), p+1);

        bool p_ko_nahi_lo = solve(n, p+1);

        return p_ko_lelo || p_ko_nahi_lo;
    }

int solve(int parent, int n, int k){
        if(n == 0) return parent;

        int mid = 1 << (n - 1);
        if(k < mid) return solve(parent == 0 ? 0 : 1, n - 1, k);
        return solve(parent == 0 ? 1 : 0, n - 1, k - mid);
    }

int solve(int y, int x, int s) {
    if(s == 2) return 2 * y + x;
    s >>= 1;
    int ny = y / s, nx = x / s;
    int nxt = ny * 2 + nx;
    return s * s * nxt + solve(y - ny * s, x - nx * s, s);
}

int solve(vector<int>& cost, int idx) {
        if(idx >= cost.size())
            return 0; //when you reach top, you don't have to pay anything

        int move_one = cost[idx] + solve(cost, idx+1);
        int move_two = cost[idx] + solve(cost, idx+2);

        return min(move_one, move_two);
    }

int solve(vector<int>& nums, int l, int r, int target) {
        if(l > r)
            return -1;

        int mid = l + (r-l)/2;

        if(nums[mid] == target)
            return mid;
        else if(nums[mid] < target)
            return solve(nums, mid+1, r, target);
        else
            return solve(nums, l, mid-1, target);
    }

int ternary_search(vector<int> ar,int l,int r, int x)
{
    if(r>=l)
    {
        int mid1 = l + (r-l)/3;
        int mid2 = r - (r-l)/3;
        if(ar[mid1] == x)
            return mid1;
        if(ar[mid2] == x)
            return mid2;
        if(x<ar[mid1])
            return ternary_search(ar,l,mid1-1,x);
        else if(x>ar[mid2])
            return ternary_search(ar,mid2+1,r,x);
        else
            return ternary_search(ar,mid1+1,mid2-1,x);

    }
    return -1;
}

int ways(int i, string s, vector<int> &memo)
  {
    if (memo[i] > -1)
      return memo[i];
    int n = s.size();
    if (i == n)
      return memo[i] = 1;
    if (s[i] == '0')
      return memo[i] = 0;
    int ans = ways(i + 1, s, memo);
    if (i < n - 1 && (s[i] == '1' || (s[i] == '2' && s[i + 1] < '7')))
      ans += ways(i + 2, s, memo);
    return memo[i] = ans;
  }

ll euclid(ll a, ll b, ll &x, ll &y) {
    if (!b) return x = 1, y = 0, a;
    ll d = euclid(b, a % b, y, x);
    return y -= a/b * x, d;
}

ll fast_exp_mod(ll b, ll e, ll m){
    if(e == 0) return 1;
    if(e == 1) return b%m;
    if(e % 2 == 0){
        ll x = fast_exp_mod(b, e>>1, m);
        return mult(x,x,m);
    }
    return mult(fast_exp_mod(b, e-1, m), b, m);
}

