pair<int, int> extendedEuclid(int a, int b) {
    if (b == 0) return { 1, 0 };

    pair<int, int> p = extendedEuclid(b, a % b); // the same as gcd

    int s = p.first;
    int t = p.second;

    return { t, s - t * (a / b) };
}

pair<int, int> extendedEuclid(int a, int b) {
    if (b == 0) {
        return { 1, 0 };
    }

    pair<int, int> p = extendedEuclid(b, a % b);

    int s = p.first;
    int t = p.second;

    return { t, s - t * (a / b) };
}

static void exgcd(ll a, ll b, ll &g, ll &x, ll &y) {
    if (!b) x = 1, y = 0, g = a;
    else {
      exgcd(b, a % b, g, y, x);
      y -= x * (a / b);
    }
  }

string countAndSay(int n)
  {
    if (n == 1)
      return "1";
    auto prev_ans = countAndSay(n - 1);

    string ans = "";
    int N = prev_ans.size(), count = 1;

    for (int i = 0; i < N; ++i)
    {
      if (i == N - 1)
      {
        ans += to_string(count);
        ans += prev_ans[i];
      }
      else if (prev_ans[i] == prev_ans[i + 1])
        count++;
      else
      {
        ans += to_string(count);
        ans += prev_ans[i];
        count = 1;
      }
    }

    return ans;
  }

string countAndSay(int n)
  {
    if (n == 1)
      return "1";
    string sub = countAndSay(n - 1);
    string ans = "";

    char prev = sub[0];
    int count = 1;

    for (int i = 1; i <= sub.size(); ++i)
    {
      if (i == sub.size())
      {
        ans += to_string(count) + prev;
        break;
      }

      if (sub[i] == prev)
        count++;
      else
      {
        ans += to_string(count) + prev;
        prev = sub[i];
        count = 1;
      }
    }
    return ans;
  }

