string dfs(const vector<int>& cost, int target,
               vector<string>& dp, vector<bool>& visited){

        if(visited[target]) return dp[target];

        string res = "";
        for(int i = 8; i >= 0; i --)
            if(target > cost[i]){
                string tres = dfs(cost, target - cost[i], dp, visited);
                if(tres != "" && tres.size() + 1 > res.size())
                    res = string(1, '0' + (1 + i)) + tres;
            }
            else if(target == cost[i] && res.size() == 0)
                res += ('0' + (1 + i));

        visited[target] = true;
        return dp[target] = res;
    }

string makeLargestSpecial(string S) {

        if(S == "") return "";

        vector<string> v;
        int cnt = 0;
        for(int start = 0, i = 0; i < S.size(); i ++){
            cnt += (S[i] == '1' ? 1 : -1);
            if(!cnt){
                v.push_back("1" + makeLargestSpecial(S.substr(start + 1, i - start - 1)) + "0");
                start = i + 1;
            }
        }

        sort(v.begin(), v.end(), greater<string>());
        string res = "";
        for(const string& e: v) res += e;
        return res;
    }

