    }

unsigned int gcd(unsigned int x, unsigned int y) {
    if (x == 0) {
        return y;
    }
    if (y == 0) {
        return x;
    }
    if (x == y) {
        return x;
    }
    if (x > y) {
        // The following is valid because we have checked whether y == 0

        unsigned int temp = x / y;
        return gcd(y, x - temp * y);
    }
    // Again the following is valid because we have checked whether x == 0

    unsigned int temp = y / x;
    return gcd(x, y - temp * x);
}

using namespace std;
bool checkStr(string str,int P,int Q) {
    int N=str.size();
    char prev=str[0];
    int cnt=0;
    for(int i=0;i<N;i ++) {
        if(str[i]== prev) {
            cnt++;
        }
        else {
            if(prev=='1'&&cnt>=Q) {
                return false ;
            }
            if(prev=='0'&&cnt>=P) {
                return false ;
            }
            cnt=1 ;
        }
        prev=str[i];
    }
    if(prev=='1'&&cnt>=Q) {
        return false ;
    }
    if(prev=='0'&&cnt>=P) {
        return false ;
    }
    return true ;
}
int cntBinStr(string str,int N,int P,int Q) {
    int len=str.size();
    if(len==N) {
        if(checkStr(str,P,Q)) return 1;
        return 0 ;
    }
    int X=cntBinStr(str+'0',N,P,Q);
    int Y=cntBinStr(str+'1',N,P,Q);
    return X+Y;
}

