const int INF=1e7;
int min_op(int cur,int M) {
    if(cur>M)return INF;
    if(cur==M)return 0;
    int op=INF;
    for(int i=2;i*i<=cur;i ++) {
        if(cur%i==0) {
            if(i%2==0) {
                op=min(op,1+min_op(cur+i,M)) ;
            }
            if(( cur/i)!= i &&(cur/i)% 2==0) {
                op=min(op,1+min_op(cur +(cur/i), M)) ;
            }
        }
    }
    return op ;
}
int min_operations(int N,int M) {
    int op=min_op(N,M);
    if(op>=INF)cout<<" - 1";
    else cout<<op<<" STR";
}

using namespace std;
const int MAX=INT_MAX;
map<string,int>m;
int Min=INT_MAX;
int minOperation(string&s,int i,int j,int count) {
    if(( i>=s.size()&&j<0)||(i==j)) return MAX;
    if(s[i]== s[j]||(count>=Min)) return count;
    string str=to_string(i)+ " | "+to_string(j);
    if(m.find(str)== m.end()) {
        if(i>=s.size())m[str]= minOperation(s,i,j-1,count+1);
        else if(j<0)m[str]= minOperation(s,i+1,j,count+1);
        else m[str]= min(minOperation(s,i,j-1,count+1), minOperation(s,i+1,j,count+1)) ;
    }
    if(m[str]< Min)Min=m[str];
    return m[str];
}

