const int MAX_DIGITS=6;
int getValue(const string&str,int i,int m) {
    if(i+m>str.length())return -1;
    int value=0;
    for(int j=0;j<m;j ++) {
        int c=str[i+j]- '0';
        if(c<0 c>9)return -1;
        value=value*10+c ;
    }
    return value ;
}
int findMissingNumber(const string&str) {
    for(int m=1;m<=MAX_DIGITS;++ m) {
        int n=getValue(str,0,m);
        if(n==-1)break;
        int missingNo=-1;
        bool fail=false;
        for(int i=m;i!=str.length();i+=1+log10l(n)) {
            if(( missingNo==-1)&&(getValue(str,i,1+log10l(n+2))==n+2)) {
                missingNo=n+1;
                n+=2 ;
            }
            else if(getValue(str,i,1+log10l(n+1))==n+1)n ++;
            else {
                fail=true;
                break ;
            }
        }
        if(! fail)return missingNo ;
    }
}

using namespace std;
const int Mod=1e9+7;
int power(int X,int Y,int Mod) {
    if(Y==0)return 1;
    int p=power(X,Y/2,Mod)% Mod;
    p =(p*p)% Mod;
    if(Y&1) {
        p =(X*p)% Mod ;
    }
    return p ;
}
int Inversefactorial(int N) {
    if(N<=0)return 1;
    int fact=1;
    for(int i=1;i<=N;i ++) {
        fact =(fact*i)% Mod ;
    }
    return power(fact,Mod-2,Mod);
}
int factorial(int N) {
    if(N<=0)return 1;
    int fact=1;
    for(int i=1;i<=N;i ++) {
        fact =(fact*i)% Mod ;
    }
    return fact ;
}
int nck(int N,int K) {
    int factN=factorial(N);
    int inv=Inversefactorial(K);
    int invFact=Inversefactorial(N-K);
    return(((factN*inv)% Mod)* invFact)% Mod ;
}
int TotalWaYs(int N,int M) {
    if(( N+M)% 3!=0)return 0;
    int X=N -(N+M)/ 3;
    int Y=M -(N+M)/ 3;
    if(X<0 Y<0)return 0;
    return nck(X+Y,Y);
}

using namespace std;
const int V=5;
void DFS(bool graph[][V], bool marked[],int n,int vert,int start,int&count) {
    marked[vert]= true;
    if(n==0) {
        marked[vert]= false;
        if(graph[vert ][start]) {
            count ++;
            return ;
        }
        else return ;
    }
    for(int i=0;i<V;i ++)if(! marked[i]&& graph[vert ][i]) DFS(graph,marked,n-1,i,start,count);
    marked[vert]= false ;
}
int countCycles(bool graph[][V], int n) {
    bool marked[V];
    memset(marked,0,sizeof(marked));
    int count=0;
    for(int i=0;i<V -(n-1); i ++) {
        DFS(graph,marked,n-1,i,i,count);
        marked[i]= true ;
    }
    return count/2;
}

