double Square(double n,double i,double j) {
    double mid =(i+j)/ 2;
    double mul=mid*mid;
    if(( mul==n)||(abs(mul-n)< 0.00001)) return mid;
    else if(mul<n)return Square(n,mid,j);
    else return Square(n,i,mid);
}
void findSqrt(double n) {
    double i=1;
    bool found=false;
    while(! found) {
        if(i*i==n) {
            cout<<fixed<<setprecision(0)<< i;
            found=true ;
        }
        else if(i*i>n) {
            double res=Square(n,i-1,i);
            cout<<fixed<<setprecision(5)<< res;
            found=true ;
        }
        i++;
    }
}

using namespace std;
int Find(vector<int >&parent,int a) {
    return parent[a]=(parent[a]== a)? a :(Find(parent,parent[a]));
}
void Union(vector<int >&parent,vector<int >&rank,vector<int >&maxValue,int a,int b) {
    a=Find(parent,a);
    b=Find(parent,b);
    if(a==b)return;
    if(rank[a]== rank[b]) {
        rank[a]++ ;
    }
    if(rank[a]< rank[b]) {
        int temp=a;
        a=b;
        b=temp ;
    }
    parent[b]= a;
    maxValue[a]= max(maxValue[a], maxValue[b]) ;
}
void findMaxValueOfSet(vector<pair<int,int>>& arr,vector<int >&queries,int R,int N,int M) {
    vector<int>parent(R+1);
    vector<int>rank(R+1,0);
    vector<int>maxValue(R+1);
    for(int i=1;i<R+1;i ++) {
        parent[i]= maxValue[i]= i ;
    }
    for(int i=0;i<N;i ++) {
        Union(parent,rank,maxValue,arr[i ].first,arr[i ].second);
    }
    for(int i=0;i<M;i ++) {
        int P=Find(parent,queries[i]);
        cout<<maxValue[P]<< " ? " ;
    }
}

