int solve(vector<string>vec,int A,int B,int idx) {
    if(idx==vec.size() A+B==0) {
        return 0 ;
    }
    int zero=count0(vec[idx]);
    int one=vec[idx ].size()-zero;
    int inc=0;
    if(zero<=A&&one<=B) {
        inc=1+solve(vec,A-zero,B-one,idx+1);
    }
    int exc=solve(vec,A,B,idx+1);
