int countStrings(int N) {
    if(N==1)return 0;
    if(dp.find(N)!= dp.end())return dp[N];
    int ret=0;
    for(int div=1;div<=sqrt(N); div ++) {
        if(N%div==0) {
            ret +=(1<<div)- countStrings(div);
            int div2=N/div;
            if(div2!=div and div!=1)ret +=(1<<div2)- countStrings(div2);
        }
    }
    dp[N]= ret;
    return ret;
}

