void backtrack(int low, int high, int start, vector<int>& result) {
        if(start == 9)
            return;
        if(start%10 < 9) {
            start = start * 10 + (start%10) + 1;
            //example : start = 12 ,  now we need 123, so (12*10) + (12%10) + 1 = 123
            if(start>=low && start<=high)
                result.push_back(start);
            backtrack(low, high, start, result); //next, look for 1234
        } else {
            //if start = 123456789 , we need to go now for 23456789
            //Remeber that 123456789 would have started from start = 1
            //so for 23456789, we need to start from 2 i.e. (SD of start)+ 1
            //How to get MSD of 123456789   i.e. MSD = 1
            //If we divide 123456789 from pow(10, # digits -1)
            int num_digits = log10(start);
            int MSD = start/pow(10, num_digits);
            backtrack(low, high, MSD+1, result);
        }
    }

void build(int i, int l, int r, vector<int>& baskets, vector<int>& segmentTree) {
        if (l == r) {
            segmentTree[i] = baskets[l];
            return;
        }
        int m = (l + r) / 2;

        build(2*i + 1, l, m, baskets, segmentTree);
        build(2*i + 2, m + 1, r, baskets, segmentTree);

        segmentTree[i] = max(segmentTree[2*i + 1], segmentTree[2*i + 2]);
    }

void buildSegmentTree(int i, int l, int r, int segmentTree[], vector<int>& heights) {
        if (l == r) {
            segmentTree[i] = l; // Store the index
            return;
        }

        int mid = l + (r - l) / 2;
        buildSegmentTree(2 * i + 1, l, mid, segmentTree, heights);
        buildSegmentTree(2 * i + 2, mid + 1, r, segmentTree, heights);

        // Store the index of the maximum element
        segmentTree[i] = (heights[segmentTree[2 * i + 1]] >= heights[segmentTree[2 * i + 2]]) ?
                        segmentTree[2 * i + 1] : segmentTree[2 * i + 2];
    }

void buildSegmentTree(int i, int l, int r, vector<int>& segmentTree, int arr[]) {
        if(l == r) {
            segmentTree[i] = arr[l];
            return;
        }

        int mid = l + (r-l)/2;
        buildSegmentTree(2*i+1, l, mid, segmentTree, arr);
        buildSegmentTree(2*i+2, mid+1, r, segmentTree, arr);
        segmentTree[i] = segmentTree[2*i + 1] + segmentTree[2*i + 2];
    }

