void findmax(string str, string &ans, int k, int n, int i)
{
  if (k == 0)
    return;

  char maxs = str[i];

  for (int j = i + 1; j < n; j++)
  {
    maxs = max(maxs, str[j]);
  }

  if (maxs != str[i])
    k--;
  for (int j = i; j < n; j++)
  {
    if (str[j] == maxs)
    {
      swap(str[i], str[j]);
      ans = max(ans, str);
      findmax(str, ans, k, n, i + 1);
      swap(str[i], str[j]);
    }
  }
  return;
}

void generate(int idx, vector<int>& nums, vector<int>& result, vector<int>& temp, int prev) {
        if(idx >= nums.size()) {
            if(temp.size() > result.size()) {
                result = temp;
            }
            return;
        }

        if(prev == -1 || nums[idx] % prev == 0) {
            temp.push_back(nums[idx]);
            generate(idx+1, nums, result, temp, nums[idx]);
            temp.pop_back();
        }

        generate(idx+1, nums, result, temp, prev);
    }

void get_next(int m, int state, int index, int next_state,
                  vector<int>& next){

        if(index == m){
            next.push_back(next_state);
            return;
        }

        for(int color = 0; color < 3; color ++)
            if(color != state % 3){
                if(index > 0 && color == next_state % 3)
                    continue;
                get_next(m, state / 3, index + 1, next_state * 3 + color, next);
            }
    }

void get_option_states(const vector<int>& options, int index, int k, int state,
                           vector<int>& res){

        if(k == 0){
            res.push_back(state);
            return;
        }
        if(index == options.size()) return;

        for(int i = index; i < options.size(); i ++)
            get_option_states(options, i + 1, k - 1, state | (1 << options[i]), res);
    }

void heapify(int A[], int n, int i)
{
  int large = i;
  int left = 2 * i + 1, right = 2 * i + 2;

  if (left < n && A[large] < A[left])
    large = left;
  if (right < n && A[large] < A[right])
    large = right;

  // large me largest wale ka index hai hai teeno me se
  if (large == i)
    return;
  swap(A[large], A[i]);
  heapify(A, n, large);
}

void heapify(vector<int> &arr, int idx){
        int n = arr.size();
        int left = 2*idx + 1;
        int right = 2*idx + 2;

        if (idx >= n)
        return;
        int l = 2 * idx + 1;
        int r = 2 * idx + 2;
        int max;

        if (l < n && arr[l] > arr[idx]) max = l;
        else max = idx;

        if (r < n && arr[r] > arr[max]) max = r;

        if (max != idx) {
            swap(arr[max], arr[idx]);
            heapify(arr, max);
        }
    }

void insert(stack<int> &s, int t)
{
  if (s.size() == 0 || s.top() < t)
    s.push(t);
  else
  {
    int temp = s.top();
    s.pop();
    insert(s, t);
    s.push(temp);
  }
}

void insertAtBottom(stack<int>& St, int element) {
        if(St.empty()) {
            St.push(element);
            return;
        }

        int cur_top_el = St.top();
        St.pop();
        insertAtBottom(St, element);
        St.push(cur_top_el);
    }

void permute(string str, string out, set<string> &ans)
{
  if (str.size() == 0)
  {
    ans.insert(out);
    return;
  }

  for (int i = 0; i < str.size(); i++)
  {
    permute(str.substr(1), out + str[0], ans);
    rotate(str.begin(), str.begin() + 1, str.end());
  }
}

void pick(const string& s, int num, vector<string>& res, int start, const string& cur){
        if(num == 0){
            res.push_back(cur);
            return;
        }

        for(int i = start ; i <= (int)s.size() - num ; i ++)
            pick(s, num - 1, res, i + 1, cur + s[i]);

        return;
    }

